 81→/// Check if options form a yes/no pair.
 82→fn is_yes_no(options: &[PromptOption]) -> bool {
 83→    options.len() == 2
 84→        && options.iter().any(|o| o.value == "yes")
 85→        && options.iter().any(|o| o.value == "no")
 86→}
 87→
 88→fn prompt_select(prompt: &Prompt, options: &[PromptOption], term: &Term) -> Result<PromptResult> {
 89→    // Use custom yes/no prompt for y/n keyboard shortcut support
 90→    if is_yes_no(options) {
 91→        return prompt_yes_no(prompt, options, term);
 92→    }
 93→
 94→    let labels: Vec<_> = options.iter().map(|o| o.label.as_str()).collect();
 95→
 96→    let default_idx = prompt
 97→        .default
 98→        .as_ref()
 99→        .and_then(|d| options.iter().position(|o| o.value == *d))
100→        .unwrap_or(0);
101→
102→    let selection = Select::with_theme(&select_theme())
103→        .with_prompt(&prompt.question)
104→        .items(&labels)
105→        .default(default_idx)
106→        .interact_on(term)
107→        .map_err(map_dialoguer_err)?;
108→
109→    Ok(PromptResult::String(options[selection].value.clone()))
110→}
111→
112→/// Custom yes/no prompt with `›`/`·` indicators and `y`/`n` keyboard shortcuts.
113→///
114→/// Renders options below the prompt question, indented to align with
115→/// the step name. Supports arrow keys, j/k, Enter/Space, and y/n.
116→fn prompt_yes_no(prompt: &Prompt, options: &[PromptOption], term: &Term) -> Result<PromptResult> {
117→    let default_idx = prompt
118→        .default
119→        .as_ref()
120→        .and_then(|d| options.iter().position(|o| o.value == *d))
121→        .unwrap_or(0);
122→
123→    let mut sel = default_idx;
124→
125→    // Calculate indent: measure the visible width of the question text
126→    // to find where `[n/t] ` ends. We use a heuristic: find the first `]`
127→    // and add 2 for `] `.
128→    let indent = measure_text_width(&prompt.question)
129→        .min(prompt.question.find(']').map(|i| i + 2).unwrap_or(6));
130→    let pad = " ".repeat(indent);
131→
132→    let active_prefix = Style::new().bold();
133→    let active_style = Style::new().bold();
134→    let inactive_prefix = Style::new().dim();
135→    let inactive_style = Style::new().dim();
136→
137→    // Write prompt question
138→    term.write_line(&prompt.question).map_err(BivvyError::Io)?;
139→    term.hide_cursor().map_err(BivvyError::Io)?;
140→
141→    loop {
142→        // Draw option lines
143→        for (i, opt) in options.iter().enumerate() {
144→            let line = if i == sel {
145→                format!(
146→                    "{}{} {}",
147→                    pad,
148→                    active_prefix.apply_to("›"),
149→                    active_style.apply_to(&opt.label)
150→                )
151→            } else {
152→                format!(
153→                    "{}{} {}",
154→                    pad,
155→                    inactive_prefix.apply_to("·"),
156→                    inactive_style.apply_to(&opt.label)
157→                )
158→            };
159→            term.write_line(&line).map_err(BivvyError::Io)?;
160→        }
161→        term.flush().map_err(BivvyError::Io)?;
162→
163→        // Read key
164→        let key = term.read_key().map_err(BivvyError::Io)?;
165→
166→        let chosen = match key {
167→            Key::Char('y') | Key::Char('Y') => options.iter().position(|o| o.value == "yes"),
168→            Key::Char('n') | Key::Char('N') => options.iter().position(|o| o.value == "no"),
169→            Key::Enter | Key::Char(' ') => Some(sel),
170→            Key::ArrowDown | Key::Tab | Key::Char('j') => {
171→                sel = (sel + 1) % options.len();
172→                None
173→            }
174→            Key::ArrowUp | Key::BackTab | Key::Char('k') => {
175→                sel = (sel + options.len() - 1) % options.len();
176→                None
177→            }
178→            _ => None,
179→        };
180→
181→        if let Some(idx) = chosen {
182→            // Clear option lines
183→            term.clear_last_lines(options.len())
184→                .map_err(BivvyError::Io)?;
185→            // Clear the prompt question line
186→            term.clear_last_lines(1).map_err(BivvyError::Io)?;
187→            // Re-print prompt with selection (show "yes" or "no")
188→            let answer_text = if options[idx].value == "yes" {
189→                "yes"
190→            } else {
191→                "no"
192→            };
193→            term.write_line(&format!(
194→                "{} {}",
195→                prompt.question,
196→                Style::new().bold().apply_to(answer_text)
197→            ))
198→            .map_err(BivvyError::Io)?;
199→            term.show_cursor().map_err(BivvyError::Io)?;
200→
201→            return Ok(PromptResult::String(options[idx].value.clone()));
202→        }
203→
204→        // Clear option lines for redraw
205→        term.clear_last_lines(options.len())
206→            .map_err(BivvyError::Io)?;
207→    }
208→}
209→
210→fn prompt_multiselect(
211→    prompt: &Prompt,
212→    options: &[PromptOption],
213→    term: &Term,
214→) -> Result<PromptResult> {
215→    let labels: Vec<_> = options.iter().map(|o| o.label.as_str()).collect();
216→
217→    let default_values: Vec<&str> = prompt
218→        .default
219→        .as_deref()
220→        .map(|d| d.split(',').collect())
221→        .unwrap_or_default();
222→    let defaults: Vec<bool> = options
223→        .iter()
224→        .map(|o| default_values.contains(&o.value.as_str()))
225→        .collect();
226→
227→    let selections = MultiSelect::with_theme(&prompt_theme())
228→        .with_prompt(&prompt.question)
229→        .items(&labels)
230→        .defaults(&defaults)
231→        .interact_on(term)
232→        .map_err(map_dialoguer_err)?;
233→
234→    let values: Vec<String> = selections
235→        .iter()
236→        .map(|&i| options[i].value.clone())
237→        .collect();
238→
239→    Ok(PromptResult::Strings(values))
240→}
